.toggle-switch {
  position: relative;
  display: inline-block;
  width: 34px;
  height: 16px;
  cursor: pointer;
  /* Rounded sliders */
}
.toggle-switch.checkbox {
  display: flex;
  width: 20px;
  /* Checkmark to be shown in checkbox, it's hidden when not checked */
  /* Display checkmark when checked */
}
.toggle-switch.checkbox > span.uicomp-checkbox-span {
  position: absolute;
  top: 0;
  left: 0;
  height: 16px;
  width: 16px;
  border: 1px solid var(--inactiveIconsColor);
  border-radius: 4px;
}
.toggle-switch.checkbox > span.uicomp-checkbox-span.uicomp-checkbox-disable {
  background-color: var(--inactiveDefaultColor) !important;
  border: 0 !important;
}
.toggle-switch.checkbox input:checked ~ span.uicomp-checkbox-span {
  background-color: transparent;
  border: 1px solid var(--activeSelectedColor);
}
.toggle-switch.checkbox > span.uicomp-checkbox-span:after {
  content: "";
  position: absolute;
  display: none;
}
.toggle-switch.checkbox input:checked ~ span.uicomp-checkbox-span:after {
  display: block;
}
.toggle-switch.checkbox > span.uicomp-checkbox-span:after {
  left: 5px;
  top: 2px;
  width: 3px;
  height: 7px;
  border: solid var(--activeSelectedColor);
  border-width: 0 1px 1px 0;
  -webkit-transform: rotate(45deg);
  -ms-transform: rotate(45deg);
  transform: rotate(45deg);
}
.toggle-switch.checkbox > span.uicomp-checkbox-span.uicomp-checkbox-disable:after {
  border: solid #9c9c9c !important;
  border-width: 0 1px 1px 0 !important;
  top: 3px !important;
  left: 6px;
}
.toggle-switch .switch-text {
  position: absolute;
  z-index: 1;
  font-size: 8px;
  font-weight: bold;
}
.toggle-switch .switch-text-on {
  color: var(--mainModeColor) !important;
  left: 6px;
  top: 3px;
}
.toggle-switch .switch-text-off {
  color: var(--textSecondaryColor);
  right: 6px;
  top: 3px;
}
.toggle-switch input {
  opacity: 0;
  width: 0;
  height: 0;
}
.toggle-switch .slider {
  position: absolute;
  cursor: pointer;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: var(--mainModeColor);
  border: 1px solid var(--activeIconsColor);
  -webkit-transition: 0.4s;
  transition: 0.4s;
}
.toggle-switch .slider:before {
  position: absolute;
  content: "";
  height: 10px;
  width: 10px;
  left: 3px;
  top: 2px;
  background-color: var(--activeIconsColor);
  -webkit-transition: 0.4s;
  transition: 0.4s;
}
.toggle-switch input:checked + .slider {
  border: 1px solid var(--activeSelected);
  background-color: var(--activeSelected);
}
.toggle-switch input:checked + .slider:before {
  background-color: var(--mainModeColor);
  -webkit-transform: translateX(16px);
  -ms-transform: translateX(16px);
  transform: translateX(16px);
}
.toggle-switch-disabled input:checked + .slider {
  background-color: var(--inactiveBackgroundColor);
  border: 1px solid var(--inactiveBackgroundColor);
}
.toggle-switch .slider.round {
  border-radius: 8px;
}
.toggle-switch .slider.round:before {
  border-radius: 50%;
}

